var GdocsmithRunSchema = GdocsmithRunSchema_default;
var GdocsmithRunResultSchema = GdocsmithRunResultSchema_default;

// src/commands/run/command.ts
var runCommand = {
  description: "Read and edit Google Docs with batched steps: query, write, edit, remove, style, table, tab, doc, share, page.",
  handler: async (ctx) => {
    const run = ctx.inputsAs();
    const result = await runExecute(run);
    if (ctx.invocation === "cli") {
      console.log(JSON.stringify(result, null, 2));
      return;
    }
    return result;
  },
  inputSchema: GdocsmithRunSchema,
  key: "run",
  kind: "document",
  notes: `• Read the gdocsmith skill before the first run in a session.
` + `• Every step is checked and applied to an in-memory copy first; nothing is sent unless all steps and guards pass. dryRun: true returns the same result without sending. Sending happens in phases; a failure names the phases that landed.
` + `• Target content with anchors: {section} (heading text or ID), {node} (node/cell ID from query), {text} (unique substring), {body: true} (whole tab). Change the smallest scope that covers the edit.
` + "• `doc` is a raw doc ID (between /d/ and /edit) or an alias set by a doc step's `as` earlier in the same run.\n" + `• Content is markdown only. query output "markdown" is an editable copy: keep its frontmatter and tokens when writing it back.
` + `• Large results are saved to files; the response gives the paths and an outline.
` + `• Refusals list what a step would break (comments, suggestions, named ranges, heading links, chips, images). Use force: true on that step only with the user's consent.
` + "• Never compute character offsets or call the Docs API directly.",
  outputSchema: GdocsmithRunResultSchema
};
