var MCP_INSTRUCTIONS = 'gdocsmith reads and edits Google Docs through its run tool. Before the first run in a session, read the gdocsmith skill (Claude Code: skill "gdocsmith"; other clients: resource gdocsmith://docs/skill). Use run for all Google Docs work; never compute character offsets or call the Docs API directly.';
var program = {
  commands: [runCommand, statusCommand],
  description: createIdentity.desc,
  docs: {
    topics: {
      readme: {
        text: README_default
      },
      skill: {
        text: SKILL_default
      }
    }
  },
  key: createIdentity.key,
  mcpServer: {
    enabled: true,
    instructions: MCP_INSTRUCTIONS
  },
  version: "2.0.0"
};

